    /**
     * Method to retrieve the Forecast via an ForecastPrimaryKey.
     * @param 	id Long
     * @return 	Forecast
     * @exception ProcessingException - Thrown if processing any related problems
     * @exception IllegalArgumentException 
     */
    @SuppressWarnings("unused")
    @QueryHandler
    public Forecast handle( FindForecastQuery query ) 
    throws ProcessingException, IllegalArgumentException {
    	return find( query.getFilter().getForecastId() );
    }
    
    /**
     * Method to retrieve a collection of all Forecasts
     *
     * @param	query	FindAllForecastQuery 
     * @return 	List<Forecast> 
     * @exception ProcessingException Thrown if any problems
     */
    @SuppressWarnings("unused")
    @QueryHandler
    public List<Forecast> handle( FindAllForecastQuery query ) throws ProcessingException {
    	return findAll( query );
    }



/**
 * emit to subscription queries of type FindForecast,
 * but only if the id matches
 *
 * @param		entity	Forecast
 */
	protected void emitFindForecast( Forecast entity ) {
		LOGGER.info("handling emitFindForecast" );
		
	    queryUpdateEmitter.emit(FindForecastQuery.class,
	                            query -> query.getFilter().getForecastId().equals(entity.getForecastId()),
	                            entity);
	}
	
	/**
	 * unconditionally emit to subscription queries of type FindAllForecast
	 * 
	 * @param		entity	Forecast
	 */
	protected void emitFindAllForecast( Forecast entity ) {
		LOGGER.info("handling emitFindAllForecast" );
		
	    queryUpdateEmitter.emit(FindAllForecastQuery.class,
	                            query -> true,
	                            entity);
	}

